1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13	)
14	
15	// Check statuses recorded per rule in a report.
16	const (
17		StatusUnchecked   = "未检查"
18		StatusPass        = "通过"
19		StatusDefect      = "发现缺陷"
20		StatusToolMissing = "工具缺失"
21		StatusTimeout     = "超时"
22	)
23	
24	// ReportArtifact identifies the audited artifact by name and content hash.
25	type ReportArtifact struct {
26		Name string `json:"name"`
27		Hash string `json:"hash"`
28	}
29	
30	// ReportRule is one rule together with the invariant check result. The note
31	// carries the original checker description: counterexample evidence for a
32	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
33	// or an optional remark for a passing check. It is empty for reports built
34	// only from invariant booleans.
35	type ReportRule struct {
36		ID          string `json:"id"`
37		Kind        string `json:"kind"`
38		Severity    string `json:"severity"`
39		Invariant   string `json:"invariant"`
40		RequiresABI bool   `json:"requiresABI"`
41		Version     string `json:"version"`
42		Status      string `json:"status"`
43		Note        string `json:"note,omitempty"`
44	}
45	
46	// ReportFinding binds a defect to its artifact, rule, version and evidence.
47	type ReportFinding struct {
48		ArtifactHash string `json:"artifactHash"`
49		RuleID       string `json:"ruleId"`
50		Version      string `json:"version"`
51		Severity     string `json:"severity"`
52		Invariant    string `json:"invariant"`
53		Evidence     string `json:"evidence"`
54	}
55	
56	// Report is the persisted audit result.
57	type Report struct {
58		ReportID string          `json:"reportId"`
59		Artifact ReportArtifact  `json:"artifact"`
60		Rules    []ReportRule    `json:"rules"`
61		Findings []ReportFinding `json:"findings"`
62	}
63	
64	// wireArtifact is the JSON shape of an artifact in an audit submission.
65	type wireArtifact struct {
66		Name     string `json:"name"`
67		ABI      string `json:"abi"`
68		Bytecode string `json:"bytecode"`
69		Source   string `json:"source"`
70	}
71	
72	// wireRule is the JSON shape of a rule in an audit submission.
73	type wireRule struct {
74		ID          string `json:"id"`
75		Kind        string `json:"kind"`
76		Severity    string `json:"severity"`
77		Invariant   string `json:"invariant"`
78		RequiresABI bool   `json:"requiresABI"`
79		Version     string `json:"version"`
80	}
81	
82	// CheckRecord is one imported per-rule check result: the artifact hash and
83	// rule version it was produced against, the conclusion status, and the
84	// original checker note (counterexample, tool or deadline remark).
85	type CheckRecord struct {
86		ArtifactHash string
87		RuleID       string
88		Version      string
89		Status       string
90		Note         string
91	}
92	
93	// wireCheck is the JSON shape of one entry in the checks array.
94	type wireCheck struct {
95		ArtifactHash string `json:"artifactHash"`
96		RuleID       string `json:"ruleId"`
97		Version      string `json:"version"`
98		Status       string `json:"status"`
99		Note         string `json:"note"`
100	}
101	
102	// wireInput is the JSON object accepted by the audit command.
103	type wireInput struct {
104		Artifact   wireArtifact               `json:"artifact"`
105		Rules      []wireRule                 `json:"rules"`
106		Invariants map[string]json.RawMessage `json:"invariants"`
107		Checks     []wireCheck                `json:"checks"`
108	}
109	
110	// ParseAuditInput decodes an audit submission JSON object into domain values.
111	// Invariant values must be JSON booleans; any other type is an error. Any JSON
112	// object in the submission that repeats a member name rejects the whole
113	// submission: the decoder keeps only the last value silently, so a repeated
114	// invariant key would choose a conclusion by member order instead of giving
115	// one trustworthy result.
116	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
117		if dup := findDuplicateJSONMember(data); dup != nil {
118			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
119		}
120		var in wireInput
121		if err := json.Unmarshal(data, &in); err != nil {
122			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
123		}
124		invariants := make(map[string]bool, len(in.Invariants))
125		for key, raw := range in.Invariants {
126			// Only JSON true/false is a conclusion. Unmarshalling directly into a
127			// bool would turn null into the zero value false, which would falsely
128			// record a defect; require the token to be a boolean instead.
129			var token any
130			if err := json.Unmarshal(raw, &token); err != nil {
131				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
132			}
133			holds, ok := token.(bool)
134			if !ok {
135				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
136			}
137			invariants[key] = holds
138		}
139		artifact := Artifact{
140			Name:     in.Artifact.Name,
141			ABI:      in.Artifact.ABI,
142			Bytecode: in.Artifact.Bytecode,
143			Source:   in.Artifact.Source,
144		}
145		rules := make([]Rule, 0, len(in.Rules))
146		for _, wr := range in.Rules {
147			rules = append(rules, Rule{
148				ID:          wr.ID,
149				Kind:        wr.Kind,
150				Severity:    wr.Severity,
151				Invariant:   wr.Invariant,
152				RequiresABI: wr.RequiresABI,
153				Version:     wr.Version,
154			})
155		}
156		checks := make([]CheckRecord, 0, len(in.Checks))
157		for _, wc := range in.Checks {
158			checks = append(checks, CheckRecord{
159				ArtifactHash: wc.ArtifactHash,
160				RuleID:       wc.RuleID,
161				Version:      wc.Version,
162				Status:       wc.Status,
163				Note:         wc.Note,
164			})
165		}
166		return artifact, rules, invariants, checks, nil
167	}
168	
169	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
170	// bytecode and source strings contribute; field boundaries are explicit
171	// (length-prefixed) so that different splits never collide. The source is
172	// hashed as a field value, never read from disk, and the name does not
173	// participate.
174	func ArtifactHash(a Artifact) string {
175		h := sha256.New()
176		h.Write([]byte("contractsentinel-artifact-v1\n"))
177		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
178			fmt.Fprintf(h, "%d\n", len(field))
179			h.Write([]byte(field))
180		}
181		sum := h.Sum(nil)
182		return hex.EncodeToString(sum)
183	}
184	
185	// validCheckStatus reports whether status is one of the four recorded check
186	// conclusions.
187	func validCheckStatus(status string) bool {
188		switch status {
189		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
190			return true
191		}
192		return false
193	}
194	
195	// BuildReport evaluates rules against the artifact and invariant values and
196	// imported check records and produces the report to persist. Insufficient
197	// inputs (missing ABI for a rule that requires it, missing bytecode for a
198	// symbolic rule) fail the whole submission and are never recorded as defects.
199	// Imported checks are validated as a whole: unknown rules, duplicate records,
200	// unknown statuses, missing notes, hash or version mismatches, and a rule
201	// receiving both a check record and an invariant boolean all reject the
202	// submission without producing a report.
203	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
204		if artifact.Name == "" {
205			return Report{}, errInvalid("artifact name is required")
206		}
207		hash := ArtifactHash(artifact)
208		seen := make(map[string]bool, len(rules))
209		ruleByID := make(map[string]Rule, len(rules))
210		for _, rule := range rules {
211			if rule.ID == "" {
212				return Report{}, errInvalid("rule id is required")
213			}
214			if rule.Version == "" {
215				return Report{}, errInvalid("rule " + rule.ID + " version is required")
216			}
217			if seen[rule.ID] {
218				return Report{}, errInvalid("duplicate rule id " + rule.ID)
219			}
220			seen[rule.ID] = true
221			ruleByID[rule.ID] = rule
222			if rule.RequiresABI && artifact.ABI == "" {
223				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
224			}
225			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
226				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
227			}
228		}
229		checkByRule := make(map[string]CheckRecord, len(checks))
230		for _, check := range checks {
231			if check.RuleID == "" {
232				return Report{}, errInvalid("check rule id is required")
233			}
234			rule, ok := ruleByID[check.RuleID]
235			if !ok {
236				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
237			}
238			if _, dup := checkByRule[check.RuleID]; dup {
239				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
240			}
241			if check.ArtifactHash != hash {
242				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
243			}
244			if check.Version != rule.Version {
245				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
246			}
247			if !validCheckStatus(check.Status) {
248				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
249			}
250			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
251				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
252			}
253			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
254				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
255			}
256			checkByRule[check.RuleID] = check
257		}
258		report := Report{
259			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
260			Rules:    []ReportRule{},
261			Findings: []ReportFinding{},
262		}
263		for _, rule := range rules {
264			status := StatusUnchecked
265			note := ""
266			if check, ok := checkByRule[rule.ID]; ok {
267				status = check.Status
268				note = check.Note
269			} else if holds, checked := invariants[rule.Invariant]; checked {
270				if holds {
271					status = StatusPass
272				} else {
273					status = StatusDefect
274				}
275			}
276			report.Rules = append(report.Rules, ReportRule{
277				ID:          rule.ID,
278				Kind:        rule.Kind,
279				Severity:    rule.Severity,
280				Invariant:   rule.Invariant,
281				RequiresABI: rule.RequiresABI,
282				Version:     rule.Version,
283				Status:      status,
284				Note:        note,
285			})
286			if status == StatusDefect {
287				evidence := note
288				if evidence == "" {
289					evidence = "invariant " + rule.Invariant + " does not hold"
290				}
291				report.Findings = append(report.Findings, ReportFinding{
292					ArtifactHash: hash,
293					RuleID:       rule.ID,
294					Version:      rule.Version,
295					Severity:     rule.Severity,
296					Invariant:    rule.Invariant,
297					Evidence:     evidence,
298				})
299			}
300		}
301		report.ReportID = ReportID(report)
302		return report, nil
303	}
304	
305	// canonicalRule is the order-independent view of a rule used for the id. The
306	// note is omitted when empty so reports built only from invariant booleans
307	// keep their original ids.
308	type canonicalRule struct {
309		ID          string `json:"id"`
310		Kind        string `json:"kind"`
311		Severity    string `json:"severity"`
312		Invariant   string `json:"invariant"`
313		RequiresABI bool   `json:"requiresABI"`
314		Version     string `json:"version"`
315		Status      string `json:"status"`
316		Note        string `json:"note,omitempty"`
317	}
318	
319	// canonicalFinding is the order-independent view of a finding used for the id.
320	type canonicalFinding struct {
321		ArtifactHash string `json:"artifactHash"`
322		RuleID       string `json:"ruleId"`
323		Version      string `json:"version"`
324		Severity     string `json:"severity"`
325		Invariant    string `json:"invariant"`
326		Evidence     string `json:"evidence"`
327	}
328	
329	// canonicalReport is the deterministic content a report id is computed from.
330	type canonicalReport struct {
331		ArtifactHash string             `json:"artifactHash"`
332		Name         string             `json:"name"`
333		Rules        []canonicalRule    `json:"rules"`
334		Findings     []canonicalFinding `json:"findings"`
335	}
336	
337	// canonicalize renders a report into its order-independent form.
338	func canonicalize(report Report) canonicalReport {
339		cr := canonicalReport{
340			ArtifactHash: report.Artifact.Hash,
341			Name:         report.Artifact.Name,
342		}
343		for _, rule := range report.Rules {
344			cr.Rules = append(cr.Rules, canonicalRule{
345				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
346				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
347				Version: rule.Version, Status: rule.Status, Note: rule.Note,
348			})
349		}
350		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
351		for _, finding := range report.Findings {
352			cr.Findings = append(cr.Findings, canonicalFinding{
353				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
354				Version: finding.Version, Severity: finding.Severity,
355				Invariant: finding.Invariant, Evidence: finding.Evidence,
356			})
357		}
358		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
359		return cr
360	}
361	
362	// ReportID returns the content-addressed identifier of a report. The id binds
363	// the artifact hash, name, complete rule definitions, the invariant value
364	// used by each rule (unchecked and explicit pass are distinct), and the
365	// findings. Rule order, invariant key order and unrelated invariant keys do
366	// not influence it.
367	func ReportID(r Report) string {
368		data, err := json.Marshal(canonicalize(r))
369		if err != nil {
370			panic(err) // canonical values are all strings and bools
371		}
372		sum := sha256.Sum256(data)
373		return hex.EncodeToString(sum[:])
374	}
375	
376	// validateReport checks every archive legality condition against r. It is the
377	// single definition of a legal report: the id and artifact hash are 64
378	// lowercase hex characters, the id matches the content, the artifact name is
379	// present, rule ids are present and unique with non-empty versions, statuses
380	// use the five recorded values, tool-missing and timeout notes are
381	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
382	// artifact hash, version, severity, invariant and evidence match the rule.
383	// The same conditions apply to submissions and to stored archives: a
384	// recomputed id never makes an invalid report legal. fail is errInvalid for
385	// submissions and errCorrupt for stored archives.
386	func validateReport(r Report, fail func(string) error) error {
387		if !validReportID(r.ReportID) {
388			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
389		}
390		if r.Artifact.Name == "" {
391			return fail("report " + r.ReportID + " artifact name is required")
392		}
393		if !validReportID(r.Artifact.Hash) {
394			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
395		}
396		if ReportID(r) != r.ReportID {
397			return fail("report content does not match id " + r.ReportID)
398		}
399		seenRule := make(map[string]bool, len(r.Rules))
400		defectByID := make(map[string]ReportRule)
401		for _, rule := range r.Rules {
402			if rule.ID == "" {
403				return fail("report " + r.ReportID + " has a rule with an empty id")
404			}
405			if seenRule[rule.ID] {
406				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
407			}
408			seenRule[rule.ID] = true
409			if rule.Version == "" {
410				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
411			}
412			switch rule.Status {
413			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
414			default:
415				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
416			}
417			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
418				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
419			}
420			if rule.Status == StatusDefect {
421				defectByID[rule.ID] = rule
422			}
423		}
424		seenFinding := make(map[string]bool, len(r.Findings))
425		for _, f := range r.Findings {
426			if f.RuleID == "" {
427				return fail("report " + r.ReportID + " has a finding with an empty rule id")
428			}
429			rule, ok := defectByID[f.RuleID]
430			if !ok {
431				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
432			}
433			if seenFinding[f.RuleID] {
434				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
435			}
436			seenFinding[f.RuleID] = true
437			if f.ArtifactHash != r.Artifact.Hash {
438				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
439			}
440			if f.Version != rule.Version {
441				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
442			}
443			if f.Severity != rule.Severity {
444				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
445			}
446			if f.Invariant != rule.Invariant {
447				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
448			}
449			wantEvidence := rule.Note
450			if wantEvidence == "" {
451				wantEvidence = "invariant " + rule.Invariant + " does not hold"
452			}
453			if f.Evidence != wantEvidence {
454				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
455			}
456		}
457		for id := range defectByID {
458			if !seenFinding[id] {
459				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
460			}
461		}
462		return nil
463	}
464	
465	// validStoredReport validates archive contents.
466	func validStoredReport(r Report) error {
467		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
468	}
469	
470	// validSubmittedReport validates a submission before any store operation.
471	func validSubmittedReport(r Report) error {
472		return validateReport(r, func(msg string) error { return errInvalid(msg) })
473	}
474	
475	// duplicateArchiveError classifies an archive that repeats a JSON member as
476	// corrupt and names the requested report id, the decoded member name and the
477	// object carrying it (with array position and rule id when applicable).
478	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
479		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
480	}
481	
482	// loadStoredReport parses archive bytes for id and fully validates them.
483	func loadStoredReport(data []byte, id string) (Report, error) {
484		// Read-side counterpart of the submission check: json.Unmarshal silently
485		// keeps the last value for a repeated member, so an archive that writes a
486		// rule status as 发现缺陷 and then 通过 would decode to whichever came
487		// last. The recomputed id and the rule/finding correspondence all operate
488		// on that last-wins value and could therefore pass, accepting an archive
489		// with two conflicting conclusions. Any repeated member in any object
490		// makes the archive corrupt, regardless of the last value.
491		if dup := findDuplicateJSONMember(data); dup != nil {
492			return Report{}, duplicateArchiveError(id, data, dup)
493		}
494		var r Report
495		if err := json.Unmarshal(data, &r); err != nil {
496			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
497		}
498		if r.ReportID != id {
499			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
500		}
501		if err := validStoredReport(r); err != nil {
502			return Report{}, err
503		}
504		return r, nil
505	}
506	
507	// saveReportHook, when set, is invoked after the archive existence check and
508	// before the atomic publish. It lets tests simulate another process racing to
509	// claim the same report id.
510	var saveReportHook func(finalPath string)
511	
512	// SaveReport persists a report under the store directory. The store is safe
513	// for concurrent writers: identical reports share one file and all
514	// submissions succeed, different reports never overwrite each other, and
515	// readers only ever observe complete files. A submission is fully validated
516	// before any store operation, so an invalid report creates no store and no
517	// files. A pre-existing file with the same id must be a valid archive of the
518	// same report; a corrupted archive makes the submission fail while keeping the
519	// original file, even when the corruption appears only during the save. The
520	// first successfully archived bytes are never replaced by later submissions.
521	func SaveReport(dir string, r Report) error {
522		if err := validSubmittedReport(r); err != nil {
523			return err
524		}
525		if err := os.MkdirAll(dir, 0o755); err != nil {
526			return err
527		}
528		finalPath := filepath.Join(dir, r.ReportID+".json")
529		if existing, err := os.ReadFile(finalPath); err == nil {
530			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
531				return err
532			}
533			return nil
534		} else if !os.IsNotExist(err) {
535			return err
536		}
537		data, err := json.Marshal(r)
538		if err != nil {
539			return err
540		}
541		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
542		if err != nil {
543			return err
544		}
545		tmpPath := tmp.Name()
546		cleanup := func() { os.Remove(tmpPath) }
547		if _, err := tmp.Write(data); err != nil {
548			tmp.Close()
549			cleanup()
550			return err
551		}
552		if err := tmp.Sync(); err != nil {
553			tmp.Close()
554			cleanup()
555			return err
556		}
557		if err := tmp.Close(); err != nil {
558			cleanup()
559			return err
560		}
561		if saveReportHook != nil {
562			saveReportHook(finalPath)
563		}
564		if err := os.Link(tmpPath, finalPath); err != nil {
565			cleanup()
566			if os.IsExist(err) {
567				existing, readErr := os.ReadFile(finalPath)
568				if readErr != nil {
569					return readErr
570				}
571				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
572					return err
573				}
574				return nil
575			}
576			return err
577		}
578		cleanup()
579		return nil
580	}
581	
582	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
583	// hex characters; missing, corrupted or tampered archives produce a clear
584	// error. The store is only read, never created or modified.
585	func LoadReport(dir, id string) (Report, error) {
586		if !validReportID(id) {
587			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
588		}
589		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
590		if err != nil {
591			if os.IsNotExist(err) {
592				return Report{}, errNotFound("report " + id + " not found")
593			}
594			return Report{}, err
595		}
596		return loadStoredReport(data, id)
597	}
598	
599	type errNotFound string
600	
601	func (e errNotFound) Error() string { return string(e) }
602	
603	type errCorrupt string
604	
605	func (e errCorrupt) Error() string { return string(e) }
606

