1	package contractsentinel
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"reflect"
9		"strings"
10		"testing"
11	)
12	
13	// 本文件围绕读取入口 LoadReport 锁定“规则结论 ↔ 缺陷记录”的对应关系：
14	// 合法报告中每条“发现缺陷”规则恰好对应一条记录；损坏该关系的归档即使
15	// 报告 id 与归档内容相符（重算 id 后写盘），也必须被当作损坏归档拒绝，
16	// 而不是靠 id 不匹配才被发现。
17	//
18	// 关键手法：storeAndCorrupt 先写出一份 id 与内容完全相符的合法归档，再
19	// 修改字段并重新计算 id、改名为新文件写回，因此 LoadReport 的拒绝只能
20	// 来自 validateReport 的关系校验，不来自 ReportID(r) != r.ReportID 这一关。
21	
22	// writeReportWithFreshID marshals r after recomputing its content id, so the
23	// archive on disk has an id matching its content. It returns that id.
24	func writeReportWithFreshID(t *testing.T, dir string, r Report) string {
25		t.Helper()
26		r.ReportID = ReportID(r)
27		data, err := json.Marshal(r)
28		if err != nil {
29			t.Fatal(err)
30		}
31		if err := os.WriteFile(filepath.Join(dir, r.ReportID+".json"), data, 0o644); err != nil {
32			t.Fatal(err)
33		}
34		return r.ReportID
35	}
36	
37	// oneDefectFixture is a hand-built but legal report with three conclusions:
38	// one pass, one defect (with a checker note) and one unchecked, plus the single
39	// finding that belongs to the defect rule.
40	func oneDefectFixture() Report {
41		return Report{
42			Artifact: ReportArtifact{Name: "Vault", Hash: ArtifactHash(sampleArtifact())},
43			Rules: []ReportRule{
44				{ID: "r-pass", Kind: "static", Severity: "medium", Invariant: "inv-pass", Version: "1", Status: StatusPass},
45				{ID: "r-bad", Kind: "static", Severity: "high", Invariant: "inv-bad", Version: "2", Status: StatusDefect, Note: "counterexample: x"},
46				{ID: "r-none", Kind: "symbolic", Severity: "low", Invariant: "inv-none", Version: "3", Status: StatusUnchecked},
47			},
48			Findings: []ReportFinding{
49				{ArtifactHash: ArtifactHash(sampleArtifact()), RuleID: "r-bad", Version: "2", Severity: "high", Invariant: "inv-bad", Evidence: "counterexample: x"},
50			},
51		}
52	}
53	
54	// otherHash returns a structurally valid 64-hex hash that differs from h.
55	func otherHash(h string) string {
56		if strings.HasPrefix(h, "0") {
57			return strings.Repeat("a", 64)
58		}
59		return "0" + h[1:]
60	}
61	
62	// storeAndCorrupt writes r with a fresh matching id, decodes it back, applies
63	// mutate, recomputes the id and rewrites the archive under the new id. The
64	// returned archive has an id that matches its (now corrupt) content exactly.
65	func storeAndCorrupt(t *testing.T, dir string, r Report, mutate func(*Report)) string {
66		t.Helper()
67		id := writeReportWithFreshID(t, dir, r)
68		path := filepath.Join(dir, id+".json")
69		data, err := os.ReadFile(path)
70		if err != nil {
71			t.Fatal(err)
72		}
73		var stored Report
74		if err := json.Unmarshal(data, &stored); err != nil {
75			t.Fatal(err)
76		}
77		mutate(&stored)
78		stored.ReportID = ReportID(stored)
79		out, err := json.Marshal(stored)
80		if err != nil {
81			t.Fatal(err)
82		}
83		if err := os.Remove(path); err != nil {
84			t.Fatal(err)
85		}
86		if err := os.WriteFile(filepath.Join(dir, stored.ReportID+".json"), out, 0o644); err != nil {
87			t.Fatal(err)
88		}
89		return stored.ReportID
90	}
91	
92	// expectCorruptLoad loads id and asserts the read is rejected as a corrupt
93	// archive: errCorrupt (not errInvalid/errNotFound), no report returned, and the
94	// message names the involved rule.
95	func expectCorruptLoad(t *testing.T, dir, id, rule string) {
96		t.Helper()
97		got, err := LoadReport(dir, id)
98		if err == nil {
99			t.Fatalf("expected corrupt rejection, load succeeded: %+v", got)
100		}
101		var ec errCorrupt
102		if !errors.As(err, &ec) {
103			t.Fatalf("expected errCorrupt, got %T: %v", err, err)
104		}
105		if rule != "" && !strings.Contains(err.Error(), rule) {
106			t.Fatalf("error must name involved rule %q: %v", rule, err)
107		}
108	}
109	
110	// --- 合法读取：完整保留审计时的归属信息，不重新计算 ---
111	
112	func TestLoadReportPreservesFindingBinding(t *testing.T) {
113		dir := t.TempDir()
114		report := oneDefectFixture()
115		id := writeReportWithFreshID(t, dir, report)
116	
117		loaded, err := LoadReport(dir, id)
118		if err != nil {
119			t.Fatalf("legal report must load: %v", err)
120		}
121		if loaded.ReportID != id || loaded.Artifact != report.Artifact {
122			t.Fatalf("report header not preserved: %+v", loaded)
123		}
124		if len(loaded.Findings) != 1 {
125			t.Fatalf("findings = %d, want 1", len(loaded.Findings))
126		}
127		// 记录中的产物哈希、规则版本、严重级别、不变式和证据必须原样保留。
128		if f := loaded.Findings[0]; f != report.Findings[0] {
129			t.Fatalf("finding not preserved:\n got %+v\nwant %+v", f, report.Findings[0])
130		}
131		statusByID := map[string]string{}
132		for _, rl := range loaded.Rules {
133			statusByID[rl.ID] = rl.Status
134		}
135		if statusByID["r-bad"] != StatusDefect || statusByID["r-pass"] != StatusPass || statusByID["r-none"] != StatusUnchecked {
136			t.Fatalf("rule conclusions not preserved: %+v", statusByID)
137		}
138	}
139	
140	// 同一报告里两条规则检查同一不变式，仍是两个独立归属：一条通过、另一条
141	// 发现缺陷时，缺陷只能属于后者，不能按不变式名合并或转移。
142	func TestLoadReportSharedInvariantSeparateAttribution(t *testing.T) {
143		dir := t.TempDir()
144		hash := ArtifactHash(sampleArtifact())
145		report := Report{
146			Artifact: ReportArtifact{Name: "Vault", Hash: hash},
147			Rules: []ReportRule{
148				{ID: "r1", Kind: "static", Severity: "high", Invariant: "shared-inv", Version: "1", Status: StatusPass},
149				{ID: "r2", Kind: "static", Severity: "low", Invariant: "shared-inv", Version: "1", Status: StatusDefect, Note: "counterexample: shared"},
150			},
151			Findings: []ReportFinding{
152				{ArtifactHash: hash, RuleID: "r2", Version: "1", Severity: "low", Invariant: "shared-inv", Evidence: "counterexample: shared"},
153			},
154		}
155		id := writeReportWithFreshID(t, dir, report)
156	
157		loaded, err := LoadReport(dir, id)
158		if err != nil {
159			t.Fatalf("legal shared-invariant report must load: %v", err)
160		}
161		if len(loaded.Findings) != 1 || loaded.Findings[0].RuleID != "r2" {
162			t.Fatalf("defect must belong to r2 only: %+v", loaded.Findings)
163		}
164		if loaded.Findings[0].Severity != "low" {
165			t.Fatalf("finding must carry r2's severity, not r1's: %+v", loaded.Findings[0])
166		}
167	}
168	
169	// 规则保留检查说明时，缺陷证据应与原说明一致。
170	func TestLoadReportCheckNoteEvidencePreserved(t *testing.T) {
171		dir := t.TempDir()
172		hash := ArtifactHash(sampleArtifact())
173		note := "counterexample: path A->B->A"
174		report := Report{
175			Artifact: ReportArtifact{Name: "Vault", Hash: hash},
176			Rules: []ReportRule{
177				{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1", Status: StatusDefect, Note: note},
178			},
179			Findings: []ReportFinding{
180				{ArtifactHash: hash, RuleID: "r1", Version: "1", Severity: "high", Invariant: "inv", Evidence: note},
181			},
182		}
183		id := writeReportWithFreshID(t, dir, report)
184		loaded, err := LoadReport(dir, id)
185		if err != nil {
186			t.Fatalf("report with checker note must load: %v", err)
187		}
188		if got := loaded.Findings[0].Evidence; got != note {
189			t.Fatalf("evidence = %q, want the original checker note %q", got, note)
190		}
191	}
192	
193	// 由布尔不变式结果生成、没有检查说明的缺陷，保留现有自动生成证据。
194	func TestLoadReportAutoGeneratedEvidencePreserved(t *testing.T) {
195		dir := t.TempDir()
196		built, err := BuildReport(sampleArtifact(), []Rule{
197			{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1"},
198		}, map[string]bool{"inv": false}, nil)
199		if err != nil {
200			t.Fatal(err)
201		}
202		if err := SaveReport(dir, built); err != nil {
203			t.Fatal(err)
204		}
205		loaded, err := LoadReport(dir, built.ReportID)
206		if err != nil {
207			t.Fatalf("boolean-only report must load: %v", err)
208		}
209		if len(loaded.Findings) != 1 {
210			t.Fatalf("findings = %d, want 1", len(loaded.Findings))
211		}
212		want := "invariant inv does not hold"
213		if got := loaded.Findings[0].Evidence; got != want {
214			t.Fatalf("evidence = %q, want auto-generated %q", got, want)
215		}
216		if n := loaded.Rules[0].Note; n != "" {
