218		}
219	}
220	
221	// 布尔型合法报告以“重算 id 写盘”的方式读取也必须成功（与 SaveReport 路径
222	// 无关），证明无说明报告的自动证据规则在读取侧同样被接受。
223	func TestLoadReportAutogenEvidenceAcceptedWithFreshID(t *testing.T) {
224		dir := t.TempDir()
225		hash := ArtifactHash(sampleArtifact())
226		report := Report{
227			Artifact: ReportArtifact{Name: "Vault", Hash: hash},
228			Rules: []ReportRule{
229				{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1", Status: StatusDefect},
230			},
231			Findings: []ReportFinding{
