243	func TestLoadReportRejectsDuplicateFinding(t *testing.T) {
244		dir := t.TempDir()
245		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
246			stored.Findings = append(stored.Findings, stored.Findings[0])
247		})
