250	
251	// --- 损坏归属：缺陷引用不存在的规则 ---
252	
253	func TestLoadReportRejectsFindingForUnknownRule(t *testing.T) {
254		dir := t.TempDir()
255		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
256			// Point the finding at a rule that does not exist, and make every other
257			// field self-consistent (autogen evidence matching its own invariant),
258			// so the ONLY illegality is the dangling rule id. r-bad becomes a
259			// finding-less pass.
260			stored.Findings[0].RuleID = "ghost"
261			stored.Findings[0].Invariant = "ghost-inv"
262			stored.Findings[0].Evidence = "invariant ghost-inv does not hold"
263			for i := range stored.Rules {
264				if stored.Rules[i].ID == "r-bad" {
265					stored.Rules[i].Status = StatusPass
266					stored.Rules[i].Note = ""
267				}
268			}
269		})
270		expectCorruptLoad(t, dir, id, "ghost")
271	}
272	
273	// --- 损坏归属：缺陷引用状态不是“发现缺陷”的规则 ---
274	
275	func TestLoadReportRejectsFindingForPassingRule(t *testing.T) {
276		dir := t.TempDir()
277		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
278			// Retarget the finding onto r-pass and make every finding field
279			// consistent with that passing rule, so ONLY the fact that its status
280			// is 通过 (not 发现缺陷) can reject the archive. r-bad becomes a
281			// finding-less pass.
282			stored.Findings[0].RuleID = "r-pass"
283			stored.Findings[0].Version = "1"
284			stored.Findings[0].Severity = "medium"
285			stored.Findings[0].Invariant = "inv-pass"
286			stored.Findings[0].Evidence = "invariant inv-pass does not hold"
287			for i := range stored.Rules {
288				if stored.Rules[i].ID == "r-bad" {
289					stored.Rules[i].Status = StatusPass
290					stored.Rules[i].Note = ""
291				}
292			}
293		})
294		expectCorruptLoad(t, dir, id, "r-pass")
295	}
296	
297	func TestLoadReportRejectsFindingForUncheckedRule(t *testing.T) {
298		dir := t.TempDir()
299		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
300			// Same isolation for an unchecked rule: every field matches r-none,
301			// only its 未检查 status makes the attribution illegal.
302			stored.Findings[0].RuleID = "r-none"
303			stored.Findings[0].Version = "3"
304			stored.Findings[0].Severity = "low"
305			stored.Findings[0].Invariant = "inv-none"
306			stored.Findings[0].Evidence = "invariant inv-none does not hold"
307			for i := range stored.Rules {
308				if stored.Rules[i].ID == "r-bad" {
309					stored.Rules[i].Status = StatusPass
310					stored.Rules[i].Note = ""
311				}
312			}
313		})
314		expectCorruptLoad(t, dir, id, "r-none")
315	}
316	
317	// --- 损坏归属：规则声明发现缺陷却没有对应记录 ---
318	
319	func TestLoadReportRejectsDefectWithoutFinding(t *testing.T) {
320		dir := t.TempDir()
321		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
322			stored.Findings = nil
323		})
324		expectCorruptLoad(t, dir, id, "r-bad")
325	}
