13	// 本文件锁定“归档读取”侧对重复 JSON 成员的拒绝。audit 提交早已拒绝这类
14	// 数据，但读取已保存报告时 json.Unmarshal 会静默保留同名成员的最后一个
15	// 值：在原本“通过”的规则前再写一个“发现缺陷”status，只要后一个值让报告
16	// 标识与缺陷归属校验成立，整份自相矛盾的归档就会被当成可信结果读出。
17	// 任何对象（规则、缺陷记录、产物信息、顶层对象及未知字段的嵌套对象）出现
18	// 重复成员时，读取必须把整份报告归类为归档损坏，且不输出任何部分结果。
19	
20	// writeDupArchiveText marshals a legal report with a fresh matching id, then
21	// applies a purely textual mutation. Most mutations repeat a member while
22	// keeping the last value equal to the original legal one, so the recomputed
23	// id and the rule/finding correspondence would all pass: rejection can only
24	// come from the duplicate-member scan, never from ordinary validation. A
25	// couple of tests use it for benign textual edits instead.
26	func writeDupArchiveText(t *testing.T, dir string, r Report, mutate func(string) string) string {
27		t.Helper()
28		r.ReportID = ReportID(r)
29		data, err := json.Marshal(r)
30		if err != nil {
31			t.Fatal(err)
32		}
33		doc := mutate(string(data))
34		if doc == string(data) {
35			t.Fatal("test setup: mutation did not change the archive")
36		}
37		if err := os.WriteFile(filepath.Join(dir, r.ReportID+".json"), []byte(doc), 0o644); err != nil {
38			t.Fatal(err)
39		}
40		return r.ReportID
41	}
42	
43	// dupOnce replaces the first occurrence of old with new in the archive text.
44	func dupOnce(old, new string) func(string) string {
45		return func(doc string) string {
46			return strings.Replace(doc, old, new, 1)
47		}
48	}
49	
50	// expectCorruptDupLoad loads id and asserts the full corruption contract:
51	// errCorrupt naming the report id, the duplicate member and every required
52	// location fragment, with the zero report and an untouched archive.
53	func expectCorruptDupLoad(t *testing.T, dir, id string, wantSubstrings ...string) {
54		t.Helper()
55		path := filepath.Join(dir, id+".json")
56		before, err := os.ReadFile(path)
57		if err != nil {
58			t.Fatal(err)
59		}
60		got, err := LoadReport(dir, id)
61		if err == nil {
62			t.Fatalf("archive with a duplicate JSON member must be rejected, got %+v", got)
63		}
64		var ec errCorrupt
65		if !errors.As(err, &ec) {
66			t.Fatalf("duplicate members classify as errCorrupt, got %T: %v", err, err)
67		}
68		msg := err.Error()
69		if !strings.Contains(strings.ToLower(msg), "duplicate") {
70			t.Fatalf("error must state the member is duplicated: %v", err)
71		}
72		if !strings.Contains(msg, id) {
73			t.Fatalf("error must name the report id %q: %v", id, err)
74		}
75		for _, want := range wantSubstrings {
76			if !strings.Contains(msg, want) {
77				t.Fatalf("error %q must contain %q", msg, want)
78			}
79		}
80		if !reflect.DeepEqual(got, Report{}) {
81			t.Fatalf("failed read must return the zero report, got %+v", got)
82		}
83		// The corrupt archive is left exactly as it was.
84		after, err := os.ReadFile(path)
85		if err != nil {
86			t.Fatalf("corrupt archive must not be deleted: %v", err)
87		}
88		if string(after) != string(before) {
89			t.Fatal("failed read must not rewrite or repair the archive")
90		}
91	}
