}

// --- 审计保存遇到同标识已有归档：重复成员归档不能被当成保存成功 ---

func TestSaveReportDuplicateExistingArchiveNotTreatedAsSaved(t *testing.T) {
	dir := t.TempDir()
	r := oneDefectFixture()
	id := writeDupArchiveText(t, dir, r,
		dupOnce(`"status":"`+StatusPass+`"`,
			`"status":"`+StatusDefect+`","status":"`+StatusPass+`"`))
