			`"artifact":{"Name":"Other","HASH":"`+strings.Repeat("0", 64)+`","name":"Vault"`, 1)
		doc = strings.Replace(doc, `"version":"2","status"`,
			`"Version":"9.9.9","NOTE":"fake","version":"2","status"`, 1)
