		t.Fatalf("extension members must not change any comparison outcome: %+v", diff.Summary)
	}
	if got := diff.Results[1].After.Rule.Status; got != StatusDefect {
		t.Fatalf("diff must report the original defect conclusion, got %q", got)
	}
}

