		t.Fatal(err)
	}
	newID := ReportID(decoded)
	doc = strings.Replace(doc, `"reportId":"`+r.ReportID+`"`, `"reportId":"`+newID+`"`, 1)
	if err := os.WriteFile(filepath.Join(dir, newID+".json"), []byte(doc), 0o644); err != nil {
		t.Fatal(err)
	}
	return newID
